  internal static class DialogUi {
    internal static Window Window(string title,double width,double height){return new Window {Title="DeskBloom · "+title,Width=width,Height=height,MaxHeight=SystemParameters.WorkArea.Height-24,MinWidth=440,ResizeMode=ResizeMode.CanResize,WindowStartupLocation=WindowStartupLocation.CenterScreen,Background=Ui.Brush("#142136"),Foreground=Ui.Ink,FontFamily=new FontFamily("Segoe UI"),ShowInTaskbar=false};}
    internal static TextBlock Label(string text){var label=Ui.Text(L.T(text),13,Ui.Muted);label.Margin=new Thickness(0,17,0,9);return label;}
    internal static UniformGrid Palette(string[] colors,Func<int?> selected,Action<int> choose){var grid=new UniformGrid {Columns=10,Rows=3,HorizontalAlignment=HorizontalAlignment.Left};var buttons=new List<Button>();Action refresh=delegate {for(int j=0;j<buttons.Count;j++){buttons[j].BorderBrush=selected()==j?Brushes.White:Ui.Brush("#536177");buttons[j].BorderThickness=new Thickness(selected()==j?3:1);}};for(int n=0;n<colors.Length;n++){int index=n;var button=Ui.Button("",delegate {choose(index);refresh();},false);button.Width=32;button.Height=29;button.Padding=new Thickness(0);button.Margin=new Thickness(0,0,7,7);button.Background=Ui.Brush(colors[n]);button.Focusable=false;button.ToolTip=(n+1)+" · "+colors[n];System.Windows.Automation.AutomationProperties.SetName(button,L.T("Цвет")+" "+(n+1)+" "+colors[n]);buttons.Add(button);grid.Children.Add(button);}refresh();return grid;}
    internal static StackPanel Footer(Window window,Action save){var footer=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(20,14,20,18)};var cancel=Ui.Button(L.T("Отмена"),delegate {window.Close();},false);cancel.IsCancel=true;footer.Children.Add(cancel);footer.Children.Add(Ui.Button(L.T("Сохранить"),save,true));return footer;}
  }
  internal sealed class AppearanceWindow : Window {
    protected override void OnClosed(EventArgs e){Content=null;previewHeader.Child=null;previewBody.Child=null;previewIcon.Source=null;customPreview=null;iconButtons.Clear();base.OnClosed(e);}
    private readonly MainWindow main;private readonly GroupData group,draft;private readonly Image previewIcon;private readonly Border previewHeader,previewBody;private readonly TextBlock sample;private string customSource;private ImageSource customPreview;private readonly List<Button> iconButtons=new List<Button>();
    internal AppearanceWindow(MainWindow owner,GroupData data){main=owner;group=data;draft=new GroupData {Name=data.Name,Color=data.Color,BackgroundColor=data.BackgroundColor,Icon=data.Icon,IconImage=data.IconImage,IconRevision=data.IconRevision,FolderPath=data.FolderPath,TitleParts=data.TitleParts};Title="DeskBloom · "+L.T("Оформление группы");Width=568;Height=765;MaxHeight=SystemParameters.WorkArea.Height-24;MinWidth=480;MinHeight=420;WindowStartupLocation=WindowStartupLocation.CenterScreen;Background=Ui.Brush("#142136");Foreground=Ui.Ink;FontFamily=new FontFamily("Segoe UI");ShowInTaskbar=false;
      var root=new DockPanel {Background=Background};Content=root;var footer=DialogUi.Footer(this,Apply);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);var scroll=new ScrollViewer {VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};root.Children.Add(scroll);var panel=new StackPanel {Margin=new Thickness(24,8,24,8)};scroll.Content=panel;
      var preview=new StackPanel();previewHeader=new Border {CornerRadius=new CornerRadius(14),Padding=new Thickness(15),Height=66};var row=new DockPanel();previewIcon=new Image {Width=28,Height=28,Margin=new Thickness(0,0,14,0),Stretch=Stretch.Uniform};DockPanel.SetDock(previewIcon,Dock.Left);row.Children.Add(previewIcon);var title=Ui.Text(data.Name,16,Ui.Ink);Appearance.ApplyTitle(title,data);title.TextTrimming=TextTrimming.CharacterEllipsis;row.Children.Add(title);previewHeader.Child=row;preview.Children.Add(previewHeader);sample=Ui.Text(L.T("Предпросмотр группы"),12,Ui.Ink);previewBody=new Border {Padding=new Thickness(18,12,18,12),CornerRadius=new CornerRadius(0,0,12,12),Margin=new Thickness(5,0,5,0),Child=sample};preview.Children.Add(previewBody);panel.Children.Add(preview);
      panel.Children.Add(DialogUi.Label("Цвет значка и кнопки · 30 цветов"));panel.Children.Add(DialogUi.Palette(Appearance.Colors,()=>draft.Color,i=>{draft.Color=i;Preview();}));panel.Children.Add(DialogUi.Label("Фон группы · 30 цветов"));panel.Children.Add(DialogUi.Palette(Appearance.Backgrounds,()=>draft.BackgroundColor??0,i=>{draft.BackgroundColor=i;Preview();}));
      panel.Children.Add(DialogUi.Label("Значок группы · 15 значков"));var icons=new UniformGrid {Columns=8,Rows=2};for(int n=0;n<15;n++){int index=n;var button=Ui.Button("",delegate {draft.Icon=index;draft.IconImage=null;customSource=null;Preview();},false);button.Content=new Image {Source=Appearance.Glyph(index,Ui.Ink),Width=23,Height=23};button.BorderThickness=new Thickness(2);button.Width=45;button.Height=42;button.Padding=new Thickness(8);button.Margin=new Thickness(0,0,6,6);button.ToolTip=(L.Language=="ru"?Appearance.IconNamesRu:Appearance.IconNamesEn)[n];System.Windows.Automation.AutomationProperties.SetName(button,(string)button.ToolTip);icons.Children.Add(button);iconButtons.Add(button);}panel.Children.Add(icons);
      var upload=Ui.Button(L.T("Загрузить изображение…"),PickImage,false);upload.HorizontalAlignment=HorizontalAlignment.Left;upload.Margin=new Thickness(0,9,0,0);panel.Children.Add(upload);var hint=Ui.Text(L.T("Изображение масштабируется автоматически. Исходный файл сохраняется."),11,Ui.Muted);hint.TextWrapping=TextWrapping.Wrap;hint.Margin=new Thickness(0,9,0,0);panel.Children.Add(hint);Preview();
    }
    private void Preview(){previewHeader.Background=Appearance.Header(draft);previewBody.Background=Appearance.Background(draft);sample.Foreground=Appearance.BodyInk(draft);previewIcon.Source=customSource==null?Appearance.Icon(main.Data,draft):customPreview;for(int i=0;i<iconButtons.Count;i++)iconButtons[i].BorderBrush=customSource==null&&string.IsNullOrEmpty(draft.IconImage)&&draft.Icon==i?Appearance.Accent(draft):Brushes.Transparent;}
    private void PickImage(){var pick=new OpenFileDialog {Title=L.T("Значок группы"),Filter=L.T("Изображения")+"|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.ico"};if(pick.ShowDialog(this)!=true)return;try{customPreview=Ui.LoadImage(pick.FileName,96);customSource=pick.FileName;Preview();}catch(Exception e){Ui.Error(e);}}
    private void Apply(){try{if(customSource!=null){GroupAssets.SetIcon(main.Data,group,customSource);draft.IconImage=group.IconImage;draft.IconRevision=group.IconRevision;}group.Color=draft.Color;group.BackgroundColor=draft.BackgroundColor;group.Icon=draft.Icon;group.IconImage=draft.IconImage;group.IconRevision=draft.IconRevision;main.Save();main.RenderCurrent(false);DialogResult=true;}catch(Exception e){Ui.Error(e);}}
  }
  internal sealed class RenameWindow : Window {
    protected override void OnClosed(EventArgs e){Editor.IsUndoEnabled=false;Editor.Document.Blocks.Clear();Content=null;base.OnClosed(e);}
    internal readonly RichTextBox Editor;private readonly MainWindow main;private readonly GroupData group;private readonly TextBlock status;private int? selectedColor;
    internal RenameWindow(MainWindow owner,GroupData data){main=owner;group=data;Title="DeskBloom · "+L.T("Переименовать");Width=570;Height=410;MinHeight=390;MinWidth=490;MaxHeight=SystemParameters.WorkArea.Height-24;WindowStartupLocation=WindowStartupLocation.CenterScreen;Background=Ui.Brush("#142136");Foreground=Ui.Ink;FontFamily=new FontFamily("Segoe UI");ShowInTaskbar=false;
      var root=new DockPanel {Background=Background};Content=root;var footer=DialogUi.Footer(this,Apply);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);var panel=new StackPanel {Margin=new Thickness(24,6,24,0)};root.Children.Add(panel);panel.Children.Add(DialogUi.Label("Название группы"));Editor=CreateEditor(data);panel.Children.Add(Editor);var toolbar=new StackPanel {Orientation=Orientation.Horizontal,Margin=new Thickness(0,12,0,10)};toolbar.Children.Add(FormatButton("B","Жирный",EditingCommands.ToggleBold,FontWeights.Bold,FontStyles.Normal));toolbar.Children.Add(FormatButton("I","Курсив",EditingCommands.ToggleItalic,FontWeights.Normal,FontStyles.Italic));var underline=FormatButton("U","Подчёркнутый",EditingCommands.ToggleUnderline,FontWeights.Normal,FontStyles.Normal);((TextBlock)underline.Content).TextDecorations=TextDecorations.Underline;toolbar.Children.Add(underline);var reset=Ui.Button(L.T("Сбросить форматирование"),delegate {Editor.Selection.ClearAllProperties();selectedColor=null;Editor.Focus();},false);reset.Focusable=false;toolbar.Children.Add(reset);panel.Children.Add(toolbar);panel.Children.Add(DialogUi.Palette(Appearance.Colors,()=>selectedColor,i=>{selectedColor=i;Editor.Selection.ApplyPropertyValue(TextElement.ForegroundProperty,Ui.Brush(Appearance.Colors[i]));Editor.Focus();}));status=Ui.Text(L.T("Выделите текст, затем выберите цвет или стиль."),11,Ui.Muted);status.TextWrapping=TextWrapping.Wrap;panel.Children.Add(status);DataObject.AddPastingHandler(Editor,PlainPaste);Editor.PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Enter){e.Handled=true;Apply();}if(e.Key==Key.Escape){e.Handled=true;Close();}};Loaded+=delegate {Editor.Focus();Editor.SelectAll();};
    }
    private Button FormatButton(string text,string tip,RoutedUICommand command,FontWeight weight,FontStyle style){var button=Ui.Button(text,delegate {command.Execute(null,Editor);Editor.Focus();},false);button.Content=new TextBlock {Text=text,FontWeight=weight,FontStyle=style};button.ToolTip=L.T(tip);System.Windows.Automation.AutomationProperties.SetName(button,L.T(tip));button.Width=40;button.Padding=new Thickness(8);button.Focusable=false;return button;}
    internal static RichTextBox CreateEditor(GroupData data){var editor=new RichTextBox {Height=66,FontSize=16,Foreground=Ui.Ink,Background=Ui.Brush("#202F46"),BorderBrush=Ui.Brush("#53657F"),Padding=new Thickness(10),VerticalScrollBarVisibility=ScrollBarVisibility.Auto,AcceptsTab=false,AllowDrop=false,IsDocumentEnabled=false,IsInactiveSelectionHighlightEnabled=true,UndoLimit=30};SpellCheck.SetIsEnabled(editor,false);var paragraph=new Paragraph {Margin=new Thickness(0)};if(data.TitleParts!=null&&Appearance.Plain(data.TitleParts)==data.Name){foreach(var part in data.TitleParts){var run=new Run(part.Text??"");if(part.Color.HasValue)run.Foreground=Ui.Brush(Appearance.Colors[Math.Max(0,Math.Min(29,part.Color.Value))]);if(part.Bold)run.FontWeight=FontWeights.Bold;if(part.Italic)run.FontStyle=FontStyles.Italic;if(part.Underline)run.TextDecorations=TextDecorations.Underline;paragraph.Inlines.Add(run);}}else paragraph.Inlines.Add(new Run(data.Name));editor.Document=new FlowDocument(paragraph) {PagePadding=new Thickness(0),FontFamily=new FontFamily("Segoe UI"),FontSize=16,Foreground=Ui.Ink};return editor;}
    private static void PlainPaste(object sender,DataObjectPastingEventArgs e){var editor=(RichTextBox)sender;e.CancelCommand();if(e.SourceDataObject.GetDataPresent(DataFormats.UnicodeText)){string text=(string)e.SourceDataObject.GetData(DataFormats.UnicodeText);editor.Selection.Text=text.Replace("\r"," ").Replace("\n"," ").Replace("\t"," ");}}
    internal static List<TitlePart> ReadParts(RichTextBox editor){var result=new List<TitlePart>();TextPointer pointer=editor.Document.ContentStart;while(pointer!=null&&pointer.CompareTo(editor.Document.ContentEnd)<0){if(pointer.GetPointerContext(LogicalDirection.Forward)==TextPointerContext.Text){string text=pointer.GetTextInRun(LogicalDirection.Forward);TextPointer end=pointer.GetPositionAtOffset(text.Length);var range=new TextRange(pointer,end);var brush=range.GetPropertyValue(TextElement.ForegroundProperty) as SolidColorBrush;int index=-1;if(brush!=null)for(int n=0;n<30;n++)if(Appearance.Color(n)==brush.Color){index=n;break;}var part=new TitlePart {Text=text,Color=index<0?(int?)null:index,Bold=Equals(range.GetPropertyValue(TextElement.FontWeightProperty),FontWeights.Bold),Italic=Equals(range.GetPropertyValue(TextElement.FontStyleProperty),FontStyles.Italic)};var decorations=range.GetPropertyValue(Inline.TextDecorationsProperty) as TextDecorationCollection;part.Underline=decorations!=null&&decorations.Any(d=>d.Location==TextDecorationLocation.Underline);if(result.Count>0&&result[result.Count-1].SameStyle(part))result[result.Count-1].Text+=text;else result.Add(part);pointer=end;}else pointer=pointer.GetNextContextPosition(LogicalDirection.Forward);}return result;}
    internal static bool ValidName(string name){return !string.IsNullOrWhiteSpace(name)&&name!="."&&name!=".."&&name.Length<=100&&Store.SafeName(name)==name&&!name.Any(char.IsControl);}
    private void Apply(){var parts=ReadParts(Editor);string name=Appearance.Plain(parts);if(!ValidName(name)){status.Text=L.T("Введите допустимое имя папки: от 1 до 100 символов, без / \\ : * ? \" < > |.");status.Foreground=Ui.Brush("#FFB782");return;}try{Migration.MoveGroup(main.Data,group,Path.GetDirectoryName(main.Data.GroupPath(group)),name);if(group.Name!=name){if(group.Name.StartsWith(name,StringComparison.Ordinal))parts.Add(new TitlePart {Text=group.Name.Substring(name.Length)});else parts=new List<TitlePart>{new TitlePart {Text=group.Name}};}group.TitleParts=parts;main.Data.Save();main.RenderCurrent(false);DialogResult=true;}catch(Exception e){Ui.Error(e);}}
  }
